// PROTOTYPE (#73, round 2): only variant V2 is left. `_$logLevelsMacro` is a requirement only `@LogLevels`
// generates, so an app that writes `LogLevel` by hand gets a compiler error pointing at the macro.

import Foundation

public protocol LogLevel: RawRepresentable, CaseIterable, Comparable, Hashable, Sendable where RawValue == Int {

    /// The emoji shown in log statements of this level. Generated by `@LogLevels` from the `@Emoji` of each case.
    var emoji: String { get }

    /// Generated by `@LogLevels`. Don't implement it yourself: declare your levels as an enum with `@LogLevels`.
    static var _$logLevelsMacro: LogLevelsMacroMarker { get }

}

public extension LogLevel {

    /// The raw value is the priority. It is no requirement, so an enum can't replace it.
    var priority: Int { rawValue }

    /// Levels are ordered by priority, never by the order of their declaration.
    static func < (lhs: Self, rhs: Self) -> Bool { lhs.priority < rhs.priority }

}

/// Proof that a type got its `LogLevel` conformance from `@LogLevels`.
public struct LogLevelsMacroMarker: Sendable {

    /// Called by code that `@LogLevels` generates. Don't call it yourself.
    public static func _$generated() -> Self { Self() }

    private init() { }

}
